const cfg = $('Konfiguration').first().json;
const labels = $('Mealie-Kategorien holen').first().json.items || [];
const lists = $('Einkaufslisten holen').first().json.items || [];
const foods = $('Bekannte Lebensmittel holen').first().json.items || [];

const norm = (s) => (s ?? '').toString().trim().toLowerCase();

const wanted = norm(cfg.shoppingListName);
const list = lists.find((l) => norm(l.name) === wanted) || lists[0];
if (!list) {
  throw new Error('Keine Einkaufsliste in Mealie gefunden.');
}

const labelByName = new Map(labels.map((l) => [norm(l.name), l]));

// Erlaubte Zielschreibweisen: Name, Pluralform und Aliase der bekannten Lebensmittel
const knownFoodNames = new Set();
for (const f of foods) {
  if (f.name) knownFoodNames.add(norm(f.name));
  if (f.pluralName) knownFoodNames.add(norm(f.pluralName));
  for (const a of f.aliases || []) {
    if (a && a.name) knownFoodNames.add(norm(a.name));
  }
}

const ai = $input.first().json;
const extracted = Array.isArray(ai.items)
  ? ai.items
  : (ai.output && Array.isArray(ai.output.items) ? ai.output.items : []);

const unmatchedCategories = [];
const corrections = [];
const rejectedCorrections = [];

const payload = extracted
  .map((it, i) => {
    const original = (it.originalName ?? it.name ?? '').toString().trim();
    let name = ((it.name ?? '').toString().trim()) || original;

    // Eine Namenskorrektur wird nur übernommen, wenn das Ziel wirklich in Mealie existiert.
    if (norm(name) !== norm(original)) {
      if (knownFoodNames.has(norm(name))) {
        corrections.push({ from: original, to: name });
      } else {
        rejectedCorrections.push({ from: original, to: name });
        name = original;
      }
    }

    const label = labelByName.get(norm(it.category)) || null;
    if (norm(it.category) && !label) unmatchedCategories.push(it.category);

    const note = [(it.unit ?? '').toString().trim(), name].filter(Boolean).join(' ');

    const qty = Number(it.quantity);

    return {
      shoppingListId: list.id,
      note,
      quantity: Number.isFinite(qty) && qty > 0 ? qty : 1,
      isFood: false,
      labelId: label ? label.id : null,
      checked: false,
      position: i,
    };
  })
  .filter((x) => x.note);

return [
  {
    json: {
      shoppingList: { id: list.id, name: list.name },
      payload,
      stats: {
        count: payload.length,
        categorized: payload.filter((p) => p.labelId).length,
        unmatchedCategories: [...new Set(unmatchedCategories)],
        knownFoods: knownFoodNames.size,
        corrections,
        rejectedCorrections,
      },
    },
  },
];
